# harvest domains/plants from all jsonl and generators
occupied_domains=set()
occupied_plants=set()
occupied_ids=set()
sources={}

def add(kind, val, src):
    if not val: return
    if isinstance(val, (list,tuple)):
        for v in val: add(kind,v,src)
        return
    s=str(val).strip()
    if not s: return
    if kind=='domain': occupied_domains.add(s)
    elif kind=='plant': occupied_plants.add(s)
    elif kind=='id': occupied_ids.add(s)
    sources.setdefault(kind, {}).setdefault(s, []).append(src)

# jsonl
for p in sorted(Path('/tmp').glob('ttf-r*/batch-r*.jsonl')):
    try:
        for i,line in enumerate(p.read_text().splitlines(),1):
            line=line.strip()
            if not line: continue
            try:
                o=json.loads(line)
            except Exception:
                continue
            add('id', o.get('id'), str(p))
            st=o.get('state') or {}
            meta=o.get('meta') or {}
            add('domain', st.get('domain') or o.get('domain') or meta.get('domain'), str(p))
            # plant locations
            for k in ('plant','plant_name','facility','site'):
                add('plant', st.get(k) or o.get(k) or meta.get(k), str(p))
            # nested
            env=st.get('environment') or {}
            add('plant', env.get('plant') or env.get('name'), str(p))
            # scan all string values named plant
            def walk(x, path=''):
                if isinstance(x, dict):
                    for kk,vv in x.items():
                        if kk in ('plant','plant_name','facility') and isinstance(vv,str):
                            add('plant', vv, str(p)+':'+path+kk)
                        walk(vv, path+kk+'.')
                elif isinstance(x, list):
                    for j,vv in enumerate(x[:3]):
                        walk(vv, path+f'[{j}].')
            walk(o)
    except Exception as e:
        print('jsonl fail', p, e)

print('JSONL domains', len(occupied_domains))
print('JSONL plants', len(occupied_plants))
print('JSONL ids', len(occupied_ids))
