import os, re, json, glob

PLANT_RE = re.compile(r"\b([A-Z][A-Za-z]+(?:-[A-Z][A-Za-z0-9]+)+)\b")
DOMAIN_RE = re.compile(r"[a-z][a-z0-9]+(?:-[a-z0-9]+){1,6}")

plants = {}
domains = {}

def add(d, k, src):
    d.setdefault(k, []).append(src)

# jsonl state.description + meta
for p in sorted(glob.glob("/tmp/ttf-r*/batch-r*.jsonl")):
    rnd = os.path.basename(os.path.dirname(p))
    for i, line in enumerate(open(p, encoding="utf-8", errors="replace")):
        line=line.strip()
        if not line: continue
        try:
            rec=json.loads(line)
        except Exception:
            continue
        st=rec.get("state") or {}
        meta=rec.get("meta") or {}
        d=st.get("domain") or meta.get("domain")
        if d:
            add(domains, d, f"jsonl:{rnd}")
        blob = json.dumps(rec)
        for m in PLANT_RE.findall(blob):
            add(plants, m, f"jsonl:{rnd}")

# occupancy files
for p in glob.glob("/tmp/ttf-r*-occ-*.txt") + glob.glob("/tmp/ttf-r*/occ-*.txt"):
    txt=open(p, encoding="utf-8", errors="replace").read()
    for line in txt.splitlines():
        s=line.strip().strip("`")
        if not s: continue
        if re.fullmatch(r"[A-Z][A-Za-z]+(?:-[A-Z][A-Za-z0-9]+)+", s):
            add(plants, s, f"occ:{os.path.basename(p)}")
        elif re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)+", s):
            add(domains, s, f"occ:{os.path.basename(p)}")

# generators / prefixes
for p in glob.glob("/tmp/ttf-r*/gen_r*.py") + glob.glob("/tmp/ttf-r*/_*.py"):
    txt=open(p, encoding="utf-8", errors="replace").read()
    rnd=os.path.basename(os.path.dirname(p))
    # MY_PLANTS / MY_DOMAINS
    mp=re.search(r"MY_PLANTS\s*=\s*\((.*?)\)", txt, re.S)
    if mp:
        for m in re.findall(r'"([^"]+)"', mp.group(1)):
            add(plants, m, f"genMY:{rnd}")
    md=re.search(r"MY_DOMAINS\s*=\s*\((.*?)\)", txt, re.S)
    if md:
        for m in re.findall(r'"([^"]+)"', md.group(1)):
            add(domains, m, f"genMY:{rnd}")
    for m in PLANT_RE.findall(txt):
        add(plants, m, f"gen:{rnd}")

print("PLANT COUNT", len(plants))
print("DOMAIN COUNT", len(domains))

# dump unique plants
print("\n=== PLANTS ===")
for k in sorted(plants):
    srcs=sorted(set(plants[k]))
    print(f"{k}\t{srcs[0] if len(srcs)==1 else srcs[:3]}")

print("\n=== INCOMPLETE-GEN DOMAINS (r90-r95) ===")
for k,v in sorted(domains.items()):
    if any("r90" in x or "r91" in x or "r92" in x or "r93" in x or "r94" in x or "r95" in x for x in v):
        print(k, sorted(set(v))[:6])
