import os, re, json, glob
from collections import defaultdict

plants = set()
domains = set()
sources = defaultdict(list)

def add_plant(p, src):
    p = (p or "").strip()
    if not p: return
    plants.add(p)
    sources[('plant', p)].append(src)

def add_domain(d, src):
    d = (d or "").strip()
    if not d: return
    domains.add(d)
    sources[('domain', d)].append(src)

# jsonl batches
for path in sorted(glob.glob("/tmp/ttf-r*/batch-r*.jsonl")):
    try:
        with open(path) as f:
            for i, line in enumerate(f, 1):
                line=line.strip()
                if not line: continue
                try:
                    rec=json.loads(line)
                except Exception:
                    continue
                st=rec.get("state") or {}
                meta=rec.get("meta") or {}
                add_domain(st.get("domain"), path)
                add_domain(meta.get("domain"), path)
                for k in ("plant","plant_id","facility","site"):
                    add_plant(st.get(k), path)
                    add_plant(meta.get(k), path)
                # nested
                for obj in (st, meta, rec.get("proposed_action") or {}):
                    if isinstance(obj, dict):
                        for k,v in obj.items():
                            if k in ("plant","plant_name","facility","site") and isinstance(v,str):
                                add_plant(v, path)
    except Exception as e:
        print("err", path, e)

print("jsonl domains", len(domains), "plants", len(plants))

# NOTES plant/domain mentions
plant_re = re.compile(r'\b([A-Z][a-z]+(?:-[A-Z][a-z]+)+)\b')  # Name-Name invented plants
domain_line = re.compile(r'Domains this batch:\s*`([^`]+)`(?:\s*,\s*`([^`]+)`)*')

for path in sorted(glob.glob("/tmp/ttf-r*/NOTES-r*.md")):
    text=open(path).read()
    m=re.search(r'Domains this batch:\s*(.+)', text)
    if m:
        ds=re.findall(r'`([^`]+)`', m.group(1))
        for d in ds:
            add_domain(d, path)

# generators: domain strings and plant names
for path in sorted(glob.glob("/tmp/ttf-r*/**/*.py"), key=str):
    try:
        text=open(path, errors='replace').read()
    except Exception:
        continue
    for m in re.finditer(r'["\']domain["\']\s*:\s*["\']([^"\']+)["\']', text):
        add_domain(m.group(1), path)
    for m in re.finditer(r'\bdomain\s*=\s*["\']([^"\']+)["\']', text):
        add_domain(m.group(1), path)
    for m in re.finditer(r'["\']plant["\']\s*:\s*["\']([^"\']+)["\']', text):
        add_plant(m.group(1), path)

print("after gens domains", len(domains), "plants", len(plants))

# occupancy sidecars
for path in glob.glob("/tmp/ttf-r*-occ-*.txt") + glob.glob("/tmp/ttf-r*/occ-*.txt"):
    for line in open(path):
        s=line.strip()
        if not s or s.startswith('#'): continue
        # files named plants vs domains
        if 'plant' in os.path.basename(path).lower():
            add_plant(s, path)
        else:
            add_domain(s, path)

print("after occ files domains", len(domains), "plants", len(plants))
print("--- domains (sorted) ---")
for d in sorted(domains):
    print(d)
print("--- plants (sorted) ---")
for p in sorted(plants):
    print(p)
