    for line in path.read_text().splitlines():
        if not line.strip(): continue
        rec=json.loads(line)
        other=rec.get('state',{}).get('description')
        if not isinstance(other,str): continue
        for r in ours:
            v=jaccard(r['state']['description'], other)
            if v>=0.30:
                best.append((v,r['id'],rec.get('id'), path.parent.name, rec.get('state',{}).get('domain'), other[:100]))
best.sort(reverse=True)
