PLANT_RE = re.compile(r'\b([A-Z][A-Za-z]+(?:-[A-Z][A-Za-z0-9]+)+)\b')
DOM_KEYS = ('THIS_DOMAINS','MY_DOMAINS')
PLANT_KEYS = ('THIS_PLANTS','MY_PLANTS')

def add_dom(d, where):
    d=d.strip().strip('"').strip("'")
    if d and re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)+', d):
        domains.add(d); src[d].append(where)

def add_plant(p, where):
    p=p.strip().strip('"').strip("'")
    if p and '-' in p and p[0].isupper():
        plants.add(p); src[p].append(where)

# jsonl batches
for p in sorted(root.glob('ttf-r*/batch-r*.jsonl')):
