        if not line.strip(): continue
        try: r=json.loads(line)
        except Exception as e:
            print('BAD JSON', p, i, e); continue
        st=r.get('state',{}) or {}
        meta=r.get('meta',{}) or {}
        for d in (st.get('domain'), meta.get('domain'), st.get('process_domain')):
            if isinstance(d,str): add_dom(d, f'{p.name}:jsonl')
        blob=json.dumps(r)
        for m in PLANT_RE.finditer(blob):
            add_plant(m.group(1), f'{p.name}:jsonl')

# python gens
for p in sorted(root.glob('ttf-r*/*.py')):
    t=p.read_text(errors='ignore')
    for name in DOM_KEYS:
        m=re.search(rf'{name}\s*=\s*[(\{{](.*?)[)\}}]', t, re.S)
