    for name in PLANT_KEYS:
        m=re.search(rf'{name}\s*=\s*\((.*?)\)', t, re.S)
        if m:
            for s in re.findall(r'["\']([^"\']+)["\']', m.group(1)):
                add_plant(s, f'{p}')

