import os, re, json, glob
from collections import defaultdict

# Harvest domains/plants from jsonl, NOTES, gens, occ files
domains = defaultdict(set)
plants = defaultdict(set)

slug_re = re.compile(r'"domain"\s*:\s*"([^"]+)"')
plant_re = re.compile(r'"plant(?:_id|_name|_slug)?"\s*:\s*"([^"]+)"', re.I)
this_dom_re = re.compile(r'THIS_DOMAINS\s*=\s*\[(.*?)\]', re.S)
this_plant_re = re.compile(r'THIS_PLANTS\s*=\s*\[(.*?)\]', re.S)
notes_dom_re = re.compile(r'Domains this batch:\s*`([^`]+)`(?:\s*,\s*`([^`]+)`)*')
quoted = re.compile(r"'([^']+)'|\"([^\"]+)\"")

def add_from_text(src, text, kind):
    if kind == 'jsonl':
        for line in text.splitlines():
            line=line.strip()
            if not line: continue
            try:
                rec=json.loads(line)
            except Exception:
                continue
            d = rec.get('domain') or rec.get('meta',{}).get('domain') or rec.get('state',{}).get('domain')
            if d: domains[d].add(src)
            # nested
            for path in [
                rec.get('state',{}),
                rec.get('meta',{}),
                rec.get('context',{}),
            ]:
                if isinstance(path, dict):
                    for k in ('domain','plant','plant_name','site','facility'):
                        v=path.get(k)
                        if isinstance(v,str) and v:
                            if k=='domain': domains[v].add(src)
                            else: plants[v].add(src)
            # also search keys
            blob=json.dumps(rec)
            for m in re.finditer(r'"(plant(?:_name)?|site_name|facility)"\s*:\s*"([^"]+)"', blob):
                plants[m.group(2)].add(src)

paths=[]
paths += glob.glob('/tmp/ttf-r*/batch-r*.jsonl')
paths += glob.glob('/tmp/ttf-r*/NOTES-r*.md')
paths += glob.glob('/tmp/ttf-r*/gen_r*.py')
paths += glob.glob('/tmp/ttf-r*/generate*.py')
paths += glob.glob('/tmp/ttf-r*/occ-*.txt')
paths += glob.glob('/tmp/ttf-r*-occ-*.txt')
paths += glob.glob('/tmp/ttf-r*/_prefix.py')
paths += glob.glob('/tmp/ttf-r*/_records*.py')

print('files', len(paths))
for p in sorted(paths):
    try:
        text=open(p,encoding='utf-8',errors='replace').read()
    except Exception as e:
        continue
    if p.endswith('.jsonl'):
        add_from_text(p, text, 'jsonl')
        continue
    # domains in notes
    m=re.search(r'Domains this batch:\s*(.+)', text)
    if m:
        for d in re.findall(r'`([^`]+)`', m.group(1)):
            domains[d].add(p)
    # THIS_DOMAINS
    m=this_dom_re.search(text)
    if m:
        for q in quoted.finditer(m.group(1)):
            s=q.group(1) or q.group(2)
            if s: domains[s].add(p)
    m=this_plant_re.search(text)
    if m:
        for q in quoted.finditer(m.group(1)):
            s=q.group(1) or q.group(2)
            if s: plants[s].add(p)
    # occ files: one per line
    if 'occ' in os.path.basename(p) or p.endswith('occ-domains.txt') or p.endswith('occ-plants.txt'):
        for line in text.splitlines():
            s=line.strip().strip('`"\'')
            if not s or s.startswith('#'): continue
            if 'plant' in p: plants[s].add(p)
            else: domains[s].add(p)
    # invented plant names in notes: All five plants are invented (A, B, C, D, E)
    m=re.search(r'invented \(([^)]+)\)', text)
    if m:
        for part in m.group(1).split(','):
            plants[part.strip()].add(p)

print('=== DOMAINS count', len(domains))
print('=== PLANTS count', len(plants))
